ImageData build_image(const Fib& fib) {
    ImageBuilder b;
    b.add_all(fib);

    std::vector<BNode*> all;
    if (b.root0) { b.stage_walk(b.root0); b.collect(b.root0, all); }
    for (std::map<uint64_t, BNode*>::iterator it = b.roots16.begin(); it != b.roots16.end(); ++it) {
        b.stage_walk(it->second);
        b.collect(it->second, all);
    }
    for (std::map<uint64_t, BNode*>::iterator it = b.roots64.begin(); it != b.roots64.end(); ++it) {
        b.stage_walk(it->second);
        b.collect(it->second, all);
    }

    // Local ordering, node sizes, bulk groups.
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        for (size_t k = 0; k < n->locals.size(); ++k) {
            BLocal& e = n->locals[k];
            e.pos = ni_position(e.l, bits128(e.hi, e.lo, n->depth, e.l));
        }
        std::sort(n->locals.begin(), n->locals.end(),
                  [](const BLocal& a, const BLocal& c) { return a.pos < c.pos; });
        n->span = (n->type == 2 || n->type == 3 || n->type == 5) ? 2 : 1;
    }
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        if (n->type != 3) continue;
        n->bulk_bitmap = 0;
        for (size_t k = 0; k < n->children.size(); ++k) {
            BNode* c = n->children[k].second;
            c->bulk_root = true;
            c->span = 2;
            n->bulk_bitmap |= 1ull << n->children[k].first;
        }
        n->bulk_stage = n->children.empty() ? 0 : n->children[0].second->stage;
    }

    // Compact per-stage placement: bulk groups first (contiguous two cell
    // slots in increasing key order), then the remaining full slots, then the
    // half slots.  No cell inside [0,cells) is left unused.
    uint32_t cells[RAM_NUM];
    for (int s = 0; s < RAM_NUM; ++s) cells[s] = 0;
    for (size_t i = 0; i < all.size(); ++i) all[i]->cell = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        uint32_t cur = 0;
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* p = all[i];
            if (p->type != 3 || p->children.empty()) continue;
            if (p->children[0].second->stage != s) continue;
            p->bulk_base = cur;
            for (size_t k = 0; k < p->children.size(); ++k)
                p->children[k].second->cell = cur + 2u * (uint32_t)k;
            cur += 2u * (uint32_t)p->children.size();
        }
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* n = all[i];
            if (n->stage != s || n->bulk_root || n->span != 2) continue;
            n->cell = cur;
            cur += 2;
        }
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* n = all[i];
            if (n->stage != s || n->bulk_root || n->span != 1) continue;
            n->cell = cur;
            cur += 1;
        }
        cells[s] = cur;
    }

    ImageData img;
    img.root.stage = -1;
    img.root.cell = 0;
    if (b.root0) { img.root.stage = b.root0->stage; img.root.cell = b.root0->cell; }
    for (std::map<uint64_t, BNode*>::iterator it = b.roots16.begin(); it != b.roots16.end(); ++it)
        img.front16.push_back(ImageFront{it->first, ImageLoc{it->second->stage, it->second->cell}});
    for (std::map<uint64_t, BNode*>::iterator it = b.roots64.begin(); it != b.roots64.end(); ++it)
        img.front64.push_back(ImageFront{it->first, ImageLoc{it->second->stage, it->second->cell}});

    // NI pattern dictionary and the single NI value vector.
    std::vector<uint64_t> pats;
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        if (n->type > 3) continue;
        uint64_t p = 0;
        for (size_t k = 0; k < n->locals.size(); ++k) p |= 1ull << n->locals[k].pos;
        pats.push_back(p);
        n->bitmap_id = -1;
        n->ni_base = 0;
    }
    std::sort(pats.begin(), pats.end());
    pats.erase(std::unique(pats.begin(), pats.end()), pats.end());
    img.bitmaps = pats;
    {
        std::vector<uint32_t> nis;
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* n = all[i];
            if (n->type > 3) continue;
            uint64_t p = 0;
            for (size_t k = 0; k < n->locals.size(); ++k) p |= 1ull << n->locals[k].pos;
            for (size_t k = 0; k < pats.size(); ++k) if (pats[k] == p) { n->bitmap_id = (int)k; break; }
            if (p == 0) continue;
            n->ni_base = (uint32_t)nis.size();
            for (size_t k = 0; k < n->locals.size(); ++k) nis.push_back(n->locals[k].hop);
        }
        img.nexthops.swap(nis);
    }

    for (int s = 0; s < RAM_NUM; ++s) {
        img.cells[s] = cells[s];
        img.banks[s].assign((size_t)((cells[s] + 1) / 2), std::bitset<256>());
    }

    // Node records.  BMP is the global fallback: the longest FIB prefix of
    // length <= node depth matching the whole node region.
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        uint32_t hop = 0;
        if (fib.longest_within((uint8_t)n->depth, n->reghi, n->reglo, hop)) n->bmp = hop;
